int received = 0;
var processor = new Processor();
EventHandler handler = (_, _) => received++;
processor.Completed += handler;
processor.Run();
Console.WriteLine(received);

class Processor
{
    public event EventHandler? Completed;
    public void Run() => Completed?.Invoke(this, EventArgs.Empty);
}

